# V-001 target i_blocks / footer lifecycle (legitimate inodes have i_blocks >= 1 and footer ino == nid)

--- namei.c f2fs_new_inode sets i_blocks = 0 initially (namei.c:47-48) ---
	inode->i_ino = ino;
	inode->i_blocks = 0;

--- dir.c init_inode_metadata -> new_inode_page for FI_NEW_INODE (dir.c:400-407) ---
struct page *init_inode_metadata(struct inode *inode, struct inode *dir,
			const struct qstr *name, struct page *dpage)
{
	struct page *page;
	int err;

	if (is_inode_flag_set(F2FS_I(inode), FI_NEW_INODE)) {
		page = new_inode_page(inode);

--- node.c new_inode_page -> new_node_page (node.c:935-942) ---
struct page *new_inode_page(struct inode *inode)
{
	struct dnode_of_data dn;

	/* allocate inode page for new inode */
	set_new_dnode(&dn, inode, NULL, NULL, inode->i_ino);

--- node.c new_node_page calls inc_valid_node_count (node.c:960-963) ---
	if (unlikely(!inc_valid_node_count(sbi, dn->inode))) {
		err = -ENOSPC;
		goto fail;
	}

--- f2fs.h inc_valid_node_count increments inode->i_blocks (f2fs.h:1173-1196) ---
static inline bool inc_valid_node_count(struct f2fs_sb_info *sbi,
						struct inode *inode)
{
	...
	if (inode)
		inode->i_blocks++;
	...
}

--- node.c fill_node_footer for a new inode node (node.c:975) ---
	fill_node_footer(page, dn->nid, dn->inode->i_ino, ofs, true);

--- node.c fill_node_footer for the root inode (node.c:1790) ---
	fill_node_footer(ipage, ino, ino, 0, true);

--- node.c get_node_page rejects pages whose footer nid mismatches (node.c:1070) ---
	if (unlikely(!PageUptodate(page) || nid != nid_of_node(page))) {

Conclusion: before an inode page is written, new_node_page() calls
inc_valid_node_count() which makes inode->i_blocks >= 1, and fill_node_footer()
writes footer.ino == footer.nid. Therefore the two new guards reject only
corrupted inodes and cannot reject a legitimately created inode.

